from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[2]
chapters=json.loads((ROOT/'public/walkthrough/chapters.json').read_text(encoding='utf-8'))
scenes=json.loads((ROOT/'scripts/walkthrough/narration.json').read_text(encoding='utf-8'))
def stamp(t):return f'{int(t)//60:02}:{int(t)%60:02}'
buttons=''.join(f'<button class="chapter" data-start="{c["start"]}"><span>{stamp(c["start"])}</span><strong>{html.escape(c["title"])}</strong></button>' for c in chapters)
transcript=''.join(f'<section><h3>{stamp(c["start"])} · {html.escape(c["title"])}</h3>'+''.join(f'<p>{html.escape(t)}</p>' for t in s['sentences'])+'</section>' for s,c in zip(scenes,chapters))
